// Antialiased draws text without Core Text font smoothing, as CSS
// -webkit-font-smoothing: antialiased. Opt-in for this theme only.
Antialiased bool

// textShade preserves glyph layout and limits antialiasing to the innermost
// theme. The default theme and sibling views keep their existing rendering.
func (p *Painter) textShade(color Color) text.Shade {
	if p.Theme().Antialiased {
		return text.Flat
	}
	return text.ShadeOf(color.R, color.G, color.B)
}

